#include <stdio.h>

int main(void) {
    int K, N;
    char alphabet[100], message[1005];
    int allowed[256] = {0};

    scanf("%d %d", &K, &N);
    scanf("%s", alphabet);
    scanf("%s", message);

    for (int i = 0; i < K; i++)
        allowed[(unsigned char)alphabet[i]] = 1;

    for (int i = 0; i < N; i++) {
        if (!allowed[(unsigned char)message[i]]) {
            printf("N\n");
            return 0;
        }
    }

    printf("S\n");
